		end
		t28.GetBindState = function()
			local Bind = t28.Bind

			if not Bind then
				return true
			end

			if t28.Window.IsMobile then
				return not Bind.MobileVisible or Bind.Active == true
			end

			if Bind.Key == nil and Bind.Mode ~= "Always" then
				return true
			end

			return Bind.Active == true
		end
		t28.GetEffective = function()
			return t28.State == true and t28:GetBindState()
		end
