		t28.Set = function(p87, p88)
			t28.State = p88 == true

			if not t28.State and t28.Window.IsMobile and t28.Bind and t28.Bind.Active then
				t28.Bind:SetActive(false, true)
			end

			Frame3.BackgroundColor3 = t28.State and t28.Window.Accent or Color3.fromRGB(77, 77, 77)
			t28:ApplyEffective(true)

			if t28.Bind then
				t28.Bind:Refresh()
			end
		end
