		end)
		t2:CreateConnection(TextButton.MouseLeave, function()
			UIGradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(140, 140, 140))
		end)

		if t28.Bindable and t28.Window.CreateKeybind then
			TextLabel.Size = UDim2.new(1, -96, 1, 0)
			t28.Bind = t28.Window:CreateKeybind({
				Id = v357.BindId or v357.bindId or tostring(t28.Page and t28.Page.Image or "page") .. "|" .. t28.Section.Name .. "|" .. t28.Name,
