		local function toggle(self, o, bindable)
			pick(24):CreateToggle({
				Name = o.Text or o.Name or "Toggle",
				State = o.Default == true,
				Bindable = bindable,
				Callback = o.Callback or function() end,
			})
			if type(o.Settings) == "function" then pcall(o.Settings) end
		end
		function A:Toggle(o) toggle(self, o, false) end
		function A:ToggleKey(o) toggle(self, o, true) end
