				Max = o.Max or 100,
				Decimals = stepFor(o.Decimals),
				Suffix = (tostring(o.Suffix or ""):gsub("^%s+", "")),
				Callback = o.Callback or function() end,
			})
		end
		function A:Dropdown(o)
			local labels, codes, idx = {}, {}, 1
			for i, opt in ipairs(o.Options or {}) do
				if type(opt) == "table" then
					labels[i], codes[i] = tostring(opt.label or opt.code), opt.code
				else
					labels[i], codes[i] = tostring(opt), opt
				end
				if codes[i] == o.Default then idx = i end
			end
			pick(44):CreateDropdown({
				Name = o.Text or o.Name or "Dropdown",
				Options = labels,
				State = idx,
				Callback = function(i)
					if o.Callback then o.Callback(codes[i]) end
				end,
			})
		end
		function A:Colorpicker(o)
			pick(24):CreateColorpicker({
				Name = o.Text or o.Name or "Color",
				State = o.Default or Color3.new(1, 1, 1),
				Callback = o.Callback or function() end,
			})
		end
		function A:Button(o)
			pick(28):CreateButton({
				Name = o.Text or o.Name or "Button",
				Callback = o.Callback or function() end,
			})
		end
		function A:PlayerList(o)
			local names = {}
			for _, p in ipairs(Players:GetPlayers()) do
				if not (o.ExcludeLocal and p == localPlayer) then names[#names + 1] = p.Name end
			end
			if #names == 0 then names[1] = "(none)" end
			local picked = 1
			pick(44):CreateDropdown({
				Name = "Target player",
				Options = names,
				State = 1,
				Callback = function(i) picked = i end,
			})
			pick(28):CreateButton({
				Name = "Kill selected",
				Callback = function()
					local n = names[picked]
					if n and n ~= "(none)" and o.OnSelect then o.OnSelect({ Name = n }) end
				end,
			})
		end
		return A
	end
