-- ==========================================================
--  MM2 ROLE SOUNDS  (integrated into Misc tab)
-- ==========================================================
local SoundService = game:GetService("SoundService")

local RoleSoundLib = {
    roll = {
        {"Game (Default)", ""},
        {"Off", "Off"},
        {"Bright Click", "rbxassetid://15675059323"},
        {"Fast Click", "rbxasset://sounds/clickfast.wav"},
        {"Switch", "rbxasset://sounds/SWITCH3.wav"},
        {"Snap", "rbxasset://sounds/snap.wav"},
        {"Soft Click", "rbxassetid://16480568148"},
        {"Heavy Click", "rbxassetid://16480567946"},
        {"8-Bit Blip", "rbxassetid://16480580213"},
        {"8-Bit Beep", "rbxassetid://16480578737"},
        {"Wheel Tick", "rbxassetid://9120658649"},
        {"Ping", "rbxasset://sounds/electronicpingshort.wav"},
        {"Bubble", "rbxassetid://9112872239"}
    },
    reveal = {
        {"Game (Default)", ""},
        {"Off", "Off"},
        {"Sparkle Ding", "rbxassetid://9126073001"},
        {"Magic Chime", "rbxassetid://9116394545"},
        {"Magic Glow", "rbxassetid://9116395089"},
        {"Choir", "rbxassetid://9114792002", 3.5},
        {"Desk Bell", "rbxassetid://9125485591", 2.5},
        {"Big Bell", "rbxassetid://1034263055", 3},
        {"Stinger", "rbxassetid://15675043410"},
        {"Notify", "rbxassetid://17208361335"},
        {"Sword Draw", "rbxassetid://9119742466"},
        {"Riser", "rbxassetid://9125805579"},
        {"8-Bit Riser", "rbxassetid://16480578169"},
        {"Cymbal", "rbxassetid://9113966034", 3},
        {"Party Horn", "rbxassetid://9117240379"}
    }
}

local RoleSoundKinds = {
    ["179235828"] = "roll",
    ["179287602"] = "reveal"
}

local roleSoundCfg      = { roll = "Game (Default)", reveal = "Game (Default)", vol = 100 }
local roleSoundOriginal = {}
local roleSoundCapped   = {}

local function roleSoundGetId(id)
    if not id then return nil end
    return string.match(id, "%d+")
end

local function roleSoundFind(kind, name)
    for _, entry in ipairs(RoleSoundLib[kind] or {}) do
        if entry[1] == name then return entry end
    end
    return nil
end

local function roleSoundApply(sound)
    local original = roleSoundOriginal[sound]
    if not original then return end
    local selected = roleSoundCfg[original.kind]

    if selected == "Game (Default)" or selected == nil then
        if sound.SoundId ~= original.id then sound.SoundId = original.id end
        sound.Volume = original.vol
        return
    end

    if selected == "Off" then
        sound.Volume = 0
        return
    end

    local option = roleSoundFind(original.kind, selected)
    if not option then return end

    if sound.SoundId ~= option[2] then
        sound.SoundId = option[2]
    end
    sound.Volume = original.vol * (roleSoundCfg.vol / 100)

    if option[3] and not roleSoundCapped[sound] then
        roleSoundCapped[sound] = true
        task.delay(option[3], function()
            if sound and sound.Parent then
                pcall(function()
                    TweenService:Create(sound, TweenInfo.new(0.5), { Volume = 0 }):Play()
                end)
                task.wait(0.55)
                pcall(function() if sound then sound:Destroy() end end)
            end
        end)
    end
end

local function roleSoundTrack(sound)
    if not sound:IsA("Sound") then return end
    if roleSoundOriginal[sound] then
        roleSoundApply(sound)
        return
    end

    local id   = sound:GetAttribute("PulseOrigSound") or sound.SoundId
    local kind = RoleSoundKinds[roleSoundGetId(id) or ""]
    if not kind then return end

    roleSoundOriginal[sound] = {
        id   = id,
        vol  = tonumber(sound:GetAttribute("PulseOrigVol")) or sound.Volume,
        kind = kind
    }

    sound.Played:Connect(function()
        local original = roleSoundOriginal[sound]
        local selected = original and roleSoundFind(original.kind, roleSoundCfg[original.kind])
        if selected and selected[2]
           and selected[1] ~= "Game (Default)"
           and selected[1] ~= "Off" then
            roleSoundApply(sound)
        end
    end)

    roleSoundApply(sound)
end

local function roleSoundRefresh()
    for sound in pairs(roleSoundOriginal) do
        if sound.Parent then
            roleSoundApply(sound)
        else
            roleSoundOriginal[sound] = nil
        end
    end
end

local function roleSoundPreview(kind, selected)
    if selected == "Off" or selected == "Game (Default)" then return end
    local entry = roleSoundFind(kind, selected)
    local asset = entry and entry[2]
    if not asset or asset == "" then return end

    local sound = Instance.new("Sound")
    sound.SoundId = asset
    sound.Volume  = 0.5 * (roleSoundCfg.vol / 100)
    sound.Parent  = SoundService
    sound:Play()

    task.delay(entry[3] or 6, function()
        pcall(function()
            TweenService:Create(sound, TweenInfo.new(0.5), { Volume = 0 }):Play()
        end)
        task.wait(0.55)
        pcall(function() if sound then sound:Destroy() end end)
    end)
end

-- Attach listeners to already-playing / future sounds
task.spawn(function()
    local playerGui = Players.LocalPlayer:WaitForChild("PlayerGui", 30)
    if not playerGui then return end
    for _, d in ipairs(playerGui:GetDescendants()) do
        pcall(roleSoundTrack, d)
    end
    playerGui.DescendantAdded:Connect(function(d)
        if d:IsA("Sound") then
            task.defer(function() pcall(roleSoundTrack, d) end)
        end
    end)
end)

-- Convert the library into plain name arrays for korlox's Dropdown
local function roleSoundOptions(kind)
    local names = {}
    for i, e in ipairs(RoleSoundLib[kind]) do names[i] = e[1] end
    return names
end
local function roleSoundIndex(kind, name)
    for i, e in ipairs(RoleSoundLib[kind]) do
        if e[1] == name then return i end
    end
    return 1
end

local rollOptions   = roleSoundOptions("roll")
local revealOptions = roleSoundOptions("reveal")

v678:CreateDropdown({
    Name    = "Role Roll Sound",
    Options = rollOptions,
    State   = roleSoundIndex("roll", roleSoundCfg.roll),
    Callback = function(idx)
        roleSoundCfg.roll = rollOptions[idx]
        roleSoundRefresh()
    end
})

v678:CreateDropdown({
    Name    = "Role Reveal Sound",
    Options = revealOptions,
    State   = roleSoundIndex("reveal", roleSoundCfg.reveal),
    Callback = function(idx)
        roleSoundCfg.reveal = revealOptions[idx]
        roleSoundRefresh()
    end
})

v678:CreateButton({
    Name = "Preview Role Sounds",
    Callback = function()
        task.spawn(function()
            for _ = 1, 6 do
                roleSoundPreview("roll", roleSoundCfg.roll)
                task.wait(0.11)
            end
            roleSoundPreview("reveal", roleSoundCfg.reveal)
        end)
    end
})

















